// R-1.2 permits unwrap, expect and panic in test code. Integration tests are a
// separate crate, so the crate-level `cfg_attr(test, ...)` allowance in lib.rs
// does not reach here and has to be declared again.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

//! Contract tests against the vendored SBOL 3 corpus.
//!
//! These are expected outputs generated by pySBOL3, so they are a
//! cross-implementation oracle rather than files we wrote to pass our own
//! tests. Provenance and licence are in `testdata/sbol3/PROVENANCE.md`.

use std::path::{Path, PathBuf};

fn corpus_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../testdata/sbol3")
}

fn fixtures() -> Vec<PathBuf> {
    let mut v: Vec<_> = std::fs::read_dir(corpus_dir())
        .expect("vendored corpus must exist")
        .filter_map(Result::ok)
        .map(|e| e.path())
        .filter(|p| p.extension().is_some_and(|e| e == "ttl"))
        .collect();
    v.sort();
    v
}

#[test]
fn the_corpus_is_actually_vendored() {
    let n = fixtures().len();
    assert!(
        n >= 30,
        "expected the pySBOL3 cross-implementation corpus (33 files); found {n}. \
         A contract suite with no corpus passes vacuously."
    );
}

/// Every fixture must parse. A file the standards body's own implementation
/// produced is one we have no excuse for rejecting.
#[test]
fn every_fixture_parses() {
    let mut failures = Vec::new();
    for path in fixtures() {
        let turtle = std::fs::read_to_string(&path).expect("fixture is readable");
        if let Err(e) = integrase_sbol::from_turtle(&turtle) {
            failures.push(format!(
                "{}: {e}",
                path.file_name().unwrap().to_string_lossy()
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "fixtures failed to parse:\n{}",
        failures.join("\n")
    );
}

/// Anything the import could not carry across must be reported, not dropped.
///
/// This does not assert that nothing is lost. Plenty is: component references
/// and externally defined features do not resolve to a location, and components
/// without sequences are skipped. It asserts that loss is **visible**, which is
/// the property that matters and the one that would rot silently.
#[test]
fn every_skipped_object_is_reported() {
    for path in fixtures() {
        let turtle = std::fs::read_to_string(&path).expect("fixture is readable");
        let Ok(result) = integrase_sbol::from_turtle(&turtle) else {
            continue;
        };
        if result.designs.is_empty() {
            assert!(
                !result.report.is_silent(),
                "{}: produced no designs and no explanation. Silent loss is the failure \
                 mode this test exists to prevent.",
                path.file_name().unwrap().to_string_lossy()
            );
        }
    }
}

/// Imported designs must be internally consistent.
///
/// A feature located beyond the end of its own sequence means the adapter
/// mangled coordinates, which is the bug class most likely to appear here and
/// least likely to be noticed.
#[test]
fn imported_designs_have_in_bounds_features() {
    for path in fixtures() {
        let turtle = std::fs::read_to_string(&path).expect("fixture is readable");
        let Ok(result) = integrase_sbol::from_turtle(&turtle) else {
            continue;
        };
        for design in &result.designs {
            let bad = design.out_of_bounds_features();
            assert!(
                bad.is_empty(),
                "{}: design {} has {} feature(s) outside its sequence",
                path.file_name().unwrap().to_string_lossy(),
                design.id.0,
                bad.len()
            );
        }
    }
}

/// Provenance must record where a design came from.
#[test]
fn imported_designs_carry_import_provenance() {
    let mut checked = 0usize;
    for path in fixtures() {
        let turtle = std::fs::read_to_string(&path).expect("fixture is readable");
        let Ok(result) = integrase_sbol::from_turtle(&turtle) else {
            continue;
        };
        for design in &result.designs {
            match &design.provenance {
                integrase_core::Provenance::Imported { format, .. } => {
                    assert_eq!(format, "SBOL3");
                    checked += 1;
                }
                other => panic!("imported design has provenance {other:?}"),
            }
        }
    }
    assert!(
        checked > 0,
        "no designs were imported at all; this test proved nothing"
    );
}

/// At least one fixture must yield a design carrying sequence.
///
/// Without this, every test above could pass on a corpus that yields nothing.
#[test]
fn at_least_one_fixture_yields_a_design_with_sequence() {
    let with_sequence: usize = fixtures()
        .iter()
        .filter_map(|p| std::fs::read_to_string(p).ok())
        .filter_map(|t| integrase_sbol::from_turtle(&t).ok())
        .map(|r| r.designs.iter().filter(|d| !d.sequence.is_empty()).count())
        .sum();
    assert!(
        with_sequence > 0,
        "no fixture produced a design with sequence; the importer is not importing"
    );
}
